declare(strict_types=1); admin_required(); $route=rtrim($path,'/');
function astart(string $title,string $active):void{?><!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$title?> | Checkout 360BH</title><link rel="stylesheet" href="/assets/admin.css?v=20260924"></head><body><div class="admin-shell"><aside class="sidebar"><div class="brand">360BH<small>Checkout financeiro</small></div><nav class="nav"><a class="<?= $active==='dashboard'?'active':''?>" href="/admin">■ Visão geral</a><a href="/admin/services">⚙ Serviços</a><a href="/admin/customers">👤 Clientes</a><a class="<?= $active==='links'?'active':''?>" href="/admin/links/new">＋ Criar cobrança</a></nav><div class="sidebar-footer"><a href="/admin/logout">Sair da conta</a></div></aside><section class="main"><header class="topbar"><button class="menu-toggle" onclick="document.querySelector('.sidebar').classList.toggle('open')">☰</button><h1><?=$title?></h1><a class="btn btn-light" href="/admin/links/new">Novo link</a></header><main class="content"><?php}
function aend():void{?></main></section></div></body></html><?php}
if($route==='/admin/links/delete'&&$method==='POST'){csrf_check();db()->prepare("UPDATE payment_links SET status='CANCELED' WHERE id=? AND status='ACTIVE'")->execute([(int)($_POST['id']??0)]);header('Location: /admin');exit;}
if($route==='/admin/links/copy'&&$method==='GET'){$id=(int)($_GET['id']??0);$raw=public_token();$q=db()->prepare('SELECT id FROM payment_links WHERE id=?');$q->execute([$id]);if(!$q->fetch()){http_response_code(404);exit('Link não encontrado');}db()->prepare("UPDATE payment_links SET token_hash=?,status='ACTIVE' WHERE id=?")->execute([token_hash($raw),$id]);$url=rtrim((string)envv('APP_URL'),' /').'/pagar/'.$raw;astart('Link copiado','links');?><section class="panel"><div class="notice">Novo link público gerado.</div><input class="copy-target" readonly value="<?=htmlspecialchars($url)?>"><button class="btn copy-action" type="button">Copiar link</button><a class="btn btn-light" href="/admin">Voltar</a></section><script>document.querySelector('.copy-action').onclick=()=>navigator.clipboard.writeText(document.querySelector('.copy-target').value);</script><?php aend();exit;}
if($route==='/admin'){ $links=db()->query('SELECT id,description,amount_cents,payment_type,status FROM payment_links ORDER BY id DESC LIMIT 50')->fetchAll();$total=(int)db()->query('SELECT COUNT(*) FROM payment_links')->fetchColumn();$active=(int)db()->query("SELECT COUNT(*) FROM payment_links WHERE status='ACTIVE'")->fetchColumn();$paid=(int)db()->query("SELECT COUNT(*) FROM payment_intents WHERE status='PAID'")->fetchColumn();astart('Visão geral','dashboard');?><div class="welcome"><h2>Olá, administrador</h2><p class="muted">Acompanhe seus links e cobranças em um só lugar.</p></div><section class="cards"><div class="card"><div class="card-label">Links criados</div><div class="card-value"><?=$total?></div></div><div class="card"><div class="card-label">Links ativos</div><div class="card-value"><?=$active?></div></div><div class="card"><div class="card-label">Pagamentos aprovados</div><div class="card-value"><?=$paid?></div></div><div class="card"><div class="card-label">Gateway</div><div class="card-value" style="font-size:20px">Asaas</div></div></section><section class="panel"><div class="panel-header"><h2>Links de cobrança recentes</h2><a class="btn" href="/admin/links/new">Criar link</a></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Descrição</th><th>Valor</th><th>Tipo</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($links as $l):?><tr><td>#<?=$l['id']?></td><td><?=htmlspecialchars($l['description'])?></td><td>R$ <?=money((int)$l['amount_cents'])?></td><td><?=htmlspecialchars($l['payment_type'])?></td><td><span class="status status-<?=strtolower($l['status'])?>"><?=htmlspecialchars($l['status'])?></span></td><td><a href="/admin/links/copy?id=<?=$l['id']?>" title="Copiar link">🔗</a> <a href="/admin/links/new?edit=<?=$l['id']?>" title="Editar">✏️</a><?php if($l['status']==='ACTIVE'):?><form method="post" action="/admin/links/delete" style="display:inline" onsubmit="return confirm('Cancelar este link?')"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$l['id']?>"><button type="submit" title="Excluir">🗑️</button></form><?php endif;?></td></tr><?php endforeach;if(!$links):?><tr><td colspan="6" class="muted">Nenhum link criado ainda.</td></tr><?php endif;?></tbody></table></div></section><?php aend();exit;}
if($route==='/admin/links/new'){if($method==='POST'){csrf_check();$raw=public_token();db()->prepare('INSERT INTO payment_links(token_hash,amount_cents,currency,description,payment_type,expires_at,max_uses,created_by) VALUES(?,?,?,?,?,?,?,?)')->execute([token_hash($raw),(int)$_POST['amount_cents'],'BRL',trim($_POST['description']),$_POST['payment_type'],$_POST['expires_at']?:null,(int)$_POST['max_uses']?:1,envv('ADMIN_EMAIL')]);$url=rtrim((string)envv('APP_URL'),' /').'/pagar/'.$raw;astart('Link criado','links');?><section class="panel"><div class="notice">Link criado com sucesso.</div><p><?=htmlspecialchars($url)?></p><a class="btn" href="<?=htmlspecialchars($url)?>" target="_blank">Abrir checkout</a><a class="btn btn-light" href="/admin">Voltar</a></section><?php aend();exit;}astart('Nova cobrança','links');?><section class="panel"><form method="post"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><div class="form-grid"><div class="field full"><label>Descrição *</label><input name="description" required></div><div class="field"><label>Valor em centavos *</label><input name="amount_cents" type="number" min="1" required></div><div class="field"><label>Tipo *</label><select name="payment_type"><option value="ONE_TIME">Pagamento avulso</option><option value="SUBSCRIPTION">Assinatura mensal</option></select></div><div class="field"><label>Expiração</label><input name="expires_at" type="datetime-local"></div><div class="field"><label>Limite de utilizações</label><input name="max_uses" type="number" min="1" value="1"></div></div><button class="btn">Gerar link de pagamento</button></form></section><?php aend();exit;}
if($route==='/admin/services'||$route==='/admin/customers'){astart($route==='/admin/services'?'Serviços':'Clientes',$route==='/admin/services'?'services':'customers');?><section class="panel"><h2>Módulo em preparação</h2><p class="muted">Esta área será habilitada na próxima etapa.</p></section><?php aend();exit;}http_response_code(404);echo'Not found';
